ALTER TABLE private.signature_recipients ADD COLUMN link_ciphertext text;
ALTER TABLE private.signing_documents ADD COLUMN link_ciphertext text;
ALTER TABLE private.signature_envelopes ADD COLUMN contact_id uuid REFERENCES public.contacts(id) ON DELETE SET NULL, ADD COLUMN booking_id uuid REFERENCES public.bookings(id) ON DELETE SET NULL;
CREATE TABLE private.pdf_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE,name text NOT NULL CHECK(length(name) BETWEEN 2 AND 150),archived boolean NOT NULL DEFAULT false,current_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.pdf_template_versions(template_id uuid NOT NULL REFERENCES private.pdf_templates(id) ON DELETE CASCADE,version integer NOT NULL,pdf bytea NOT NULL,pages jsonb NOT NULL,fields jsonb NOT NULL,roles jsonb NOT NULL,message text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(template_id,version));
CREATE TABLE private.client_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE,contact_id uuid REFERENCES public.contacts(id) ON DELETE CASCADE,title text NOT NULL,completed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.workflow_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE,event_id uuid REFERENCES public.event_types(id) ON DELETE CASCADE,name text NOT NULL,trigger text NOT NULL CHECK(trigger IN ('after_booking','before_appointment','after_appointment','document_completed')),action text NOT NULL CHECK(action IN ('email_guest','email_host','prepare_agreement','send_agreement','create_task')),template_id uuid REFERENCES private.pdf_templates(id),minutes integer NOT NULL DEFAULT 60 CHECK(minutes BETWEEN 0 AND 10080),subject text NOT NULL DEFAULT '',message text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE private.workflow_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_id uuid NOT NULL REFERENCES private.workflow_rules(id),user_id uuid NOT NULL REFERENCES public."user"(id) ON DELETE CASCADE,booking_id uuid REFERENCES public.bookings(id),envelope_id uuid REFERENCES private.signature_envelopes(id),dedupe_key text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN ('queued','completed','failed','cancelled')),last_error text,created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON private.pdf_templates,private.pdf_template_versions,private.client_tasks,private.workflow_rules,private.workflow_runs FROM public,anon,authenticated;
ALTER TABLE private.delivery_jobs ADD COLUMN workflow_rule_id uuid REFERENCES private.workflow_rules(id);
